css:
.cv-grade {
  width: min(820px, 100%);
  display: grid; gap: 16px;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.cv-card {
  border: 1px solid var(--border); border-radius: 12px; overflow: hidden;
  background: var(--bg-alt);
  transition: border-color 0.2s ease;
}
.cv-card:hover { border-color: var(--accent); }

/* A moldura recorta: o zoom acontece aqui dentro e o card mantém o tamanho,
   então a grade não reflui. Scale no card faria a fileira inteira tremer. */
.cv-moldura {
  aspect-ratio: 4 / 3;
  overflow: hidden;
  display: grid; place-items: center;
  background: var(--bg);
}
.cv-foto {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform 0.5s ease;
}
.cv-card:hover .cv-foto { transform: scale(1.05); }

/* Item sem foto cai num bloco com ícone. Moldura vazia parece erro de
   carregamento; onerror na <img> pisca a imagem rota antes de sumir. */
.cv-sem-foto .cv-moldura { background: var(--bg-alt); }
.cv-vazio { width: 40px; height: 40px; color: var(--text-dimmer); }

.cv-pe { display: flex; align-items: flex-start; gap: 10px; padding: 14px 16px; }
.cv-ic { width: 16px; height: 16px; flex-shrink: 0; margin-top: 2px; color: var(--accent); }
.cv-pe h3 { margin: 0; font-family: 'Sora', sans-serif; font-size: 14px; line-height: 1.35; }
